function mergeKArrays(arrays) {
    // Binary min-heap of [value, arrayIndex, elementIndex]
    const heap = [];
    const less = (a, b) => a[0] < b[0];
    const push = (e) => {
        heap.push(e);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (!less(heap[i], heap[p])) break;
            [heap[i], heap[p]] = [heap[p], heap[i]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < heap.length && less(heap[l], heap[m])) m = l;
                if (r < heap.length && less(heap[r], heap[m])) m = r;
                if (m === i) break;
                [heap[i], heap[m]] = [heap[m], heap[i]];
                i = m;
            }
        }
        return top;
    };
    arrays.forEach((arr, i) => { if (arr.length) push([arr[0], i, 0]); });
    const out = [];
    while (heap.length) {
        const [val, i, j] = pop();
        out.push(val);
        if (j + 1 < arrays[i].length) push([arrays[i][j + 1], i, j + 1]);
    }
    return out;
}

