import java.util.*;

class Solution {
    public int[] mergeKArrays(int[][] arrays) {
        // Entries are {value, arrayIndex, elementIndex}
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int total = 0;
        for (int i = 0; i < arrays.length; i++) {
            total += arrays[i].length;
            if (arrays[i].length > 0) heap.offer(new int[]{arrays[i][0], i, 0});
        }
        int[] out = new int[total];
        int p = 0;
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            out[p++] = top[0];
            int i = top[1], j = top[2] + 1;
            if (j < arrays[i].length) heap.offer(new int[]{arrays[i][j], i, j});
        }
        return out;
    }
}

