import "container/heap"

// entry = {value, arrayIndex, elementIndex}
type arrHeap [][3]int

func (h arrHeap) Len() int            { return len(h) }
func (h arrHeap) Less(i, j int) bool  { return h[i][0] < h[j][0] }
func (h arrHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *arrHeap) Push(x interface{}) { *h = append(*h, x.([3]int)) }
func (h *arrHeap) Pop() interface{} {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func mergeKArrays(arrays [][]int) []int {
    h := &arrHeap{}
    for i, arr := range arrays {
        if len(arr) > 0 {
            *h = append(*h, [3]int{arr[0], i, 0})
        }
    }
    heap.Init(h)
    out := []int{}
    for h.Len() > 0 {
        e := heap.Pop(h).([3]int)
        out = append(out, e[0])
        if i, j := e[1], e[2]+1; j < len(arrays[i]) {
            heap.Push(h, [3]int{arrays[i][j], i, j})
        }
    }
    return out
}

