    const pop = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < heap.length && heap[l].val < heap[m].val) m = l;
                if (r < heap.length && heap[r].val < heap[m].val) m = r;
                if (m === i) break;
                [heap[i], heap[m]] = [heap[m], heap[i]];
                i = m;
            }
        }
        return top;
    };
    for (const node of lists) if (node) push(node);
    for (let i = 0; i < k - 1; i++) {
