        priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> heap(cmp);
        for (ListNode* node : lists) if (node) heap.push(node);
        for (int i = 0; i < k - 1; i++) {
            ListNode* node = heap.top();
            heap.pop();
            if (node->next) heap.push(node->next);
        }
        return heap.top()->val;
    }
};

